const _namdTR: Dict = { "nam.dominant":"Baskın Namın", "nam.dom.none":"Henüz baskın bir namın yok; davranışların seni tanımlamaya başlamadı.", "nam.dom.zalim":"İnsanlar senden çekiniyor — iyi aileler evlilik teklifini geri çevirir, ama korku işine yarar.", "nam.dom.comert":"Halk seni sever; kriz anında arkanda durur, esnaf güler yüzle karşılar.", "nam.dom.capkin":"Flörtte adın işini kolaylaştırır; ama ciddi evlilik adayları şüpheyle bakar.", "nam.dom.dindar":"Dindarlar ve rahipler sana sıcak davranır; sözün dinî çevrede geçer.", "nam.dom.mert":"İnsanlar sana güvenir; sözüne itibar edilir, kişisel meselelerde şansın artar." };
const _namdEN: Dict = { "nam.dominant":"Your Dominant Repute", "nam.dom.none":"You have no dominant repute yet; your deeds have not yet defined you.", "nam.dom.zalim":"People shrink from you — good families refuse your marriage suit, but fear serves you.", "nam.dom.comert":"The people love you; they stand by you in crisis, and merchants greet you warmly.", "nam.dom.capkin":"Your name smooths the way in courtship; but serious marriage prospects eye you with doubt.", "nam.dom.dindar":"The pious and the clergy treat you warmly; your word carries in religious circles.", "nam.dom.mert":"People trust you; your word is heeded, and your luck rises in personal matters." };
const _namdES: Dict = { "nam.dominant":"Tu Fama Dominante", "nam.dom.none":"Aún no tienes una fama dominante; tus actos todavía no te definen.", "nam.dom.zalim":"La gente te rehúye — las buenas familias rechazan tu propuesta, pero el miedo te sirve.", "nam.dom.comert":"El pueblo te quiere; te apoya en la crisis y los mercaderes te reciben con calidez.", "nam.dom.capkin":"Tu nombre allana el cortejo; pero los candidatos serios te miran con recelo.", "nam.dom.dindar":"Los devotos y el clero te tratan con calidez; tu palabra pesa en círculos religiosos.", "nam.dom.mert":"La gente confía en ti; tu palabra se escucha y tu suerte sube en asuntos personales." };
