const _lifeEN: Dict = { "dil.cocuk_kavga.t":"A Brawl at the School", "dil.cocuk_kavga.x":"A burly boy is shoving a frail benchmate around; their eyes turn to you.", "dil.cocuk_kavga.c0":"Defend the weak", "dil.cocuk_kavga.c1":"Stay out of it", "dil.cocuk_kavga.r0":"You planted yourself in his path; you took a few knocks, but that boy will never forget you.", "dil.cocuk_kavga.r1":"You lowered your head and walked on. A bitterness lingered within you.", "dil.cocuk_kese.t":"A Purse in the Mud", "dil.cocuk_kese.x":"You found a small purse in the mud. From a distance, a man seems to be watching you.", "dil.cocuk_kese.c0":"Pocket it", "dil.cocuk_kese.c1":"Find the owner", "dil.cocuk_kese.r0":"You hid the purse away. Perhaps you will remember that gaze for years to come.", "dil.cocuk_kese.r1":"You returned the purse to its owner; you became known as the 'honest child'.", "dil.cocuk_cirak.t":"The Master's Offer", "dil.cocuk_cirak.x":"The neighborhood's master craftsman offers you an apprenticeship — but it will cost you your playtime.", "dil.cocuk_cirak.c0":"Seize the trade", "dil.cocuk_cirak.c1":"Live your childhood", "dil.cocuk_cirak.r0":"You took up honest labor at a tender age; while your peers played, you learned.", "dil.cocuk_cirak.r1":"For now you chose to play; childhood is lived but once.", "dil.yetiskin_kumar.t":"The Back Room of the Han", "dil.yetiskin_kumar.x":"You are invited to the dice table in the back room of the han. There is winning to be had, and disgrace as well.", "dil.yetiskin_kumar.c0":"Take a seat", "dil.yetiskin_kumar.c1":"Get up and leave", "dil.yetiskin_kumar.r0":"The dice fell in your favor tonight; but the master of the table marked your face.", "dil.yetiskin_kumar.r1":"You kept clear of gambling; your purse is thin, but your conscience is clear.", "dil.yetiskin_yangin.t":"The Neighbor's Fire", "dil.yetiskin_yangin.x":"Your neighbor's barn has caught fire; the flames are rising, and everyone stands frozen.", "dil.yetiskin_yangin.c0":"Carry water", "dil.yetiskin_yangin.c1":"Watch from afar", "dil.yetiskin_yangin.r0":"You plunged into the blaze, hauling pails of water; the village still tells of that night.", "dil.yetiskin_yangin.r1":"You did not stir. You will be remembered as one who stood idle that night.", "dil.yasli_hac.t":"The Pilgrim Caravan", "dil.yasli_hac.x":"A caravan sets out on the road to pilgrimage. Will you join? The road is long and full of hardship.", "dil.yasli_hac.c0":"Set out", "dil.yasli_hac.c1":"Stay for now", "dil.yasli_hac.r0":"You braved the arduous road; when you returned, your name was spoken as 'hacı'.", "dil.yasli_hac.r1":"The journey waited for another spring; your intention rests in your heart.", "dil.yasli_torun.t":"A Grandchild's Curiosity", "dil.yasli_torun.x":"Your grandchild, perched on your knee, asks about your past: 'What were you like when you were young?'", "dil.yasli_torun.c0":"Tell your tale", "dil.yasli_torun.c1":"Brush it off", "dil.yasli_torun.r0":"You told of your past; their eyes lit up, and your name will live another generation.", "dil.yasli_torun.r1":"You said 'I have seen much' and left it there; some secrets go with one to the grave.", "dil.yasli_miras.t":"The Shadow of the Inheritance", "dil.yasli_miras.x":"Your children have begun to speak of the inheritance while you yet live. Word of it reached your ear.", "dil.yasli_miras.c0":"Divide it fairly", "dil.yasli_miras.c1":"Keep your counsel", "dil.yasli_miras.r0":"You declared each one's due openly; peace remained at the hearth.", "dil.yasli_miras.r1":"You held your tongue; the uncertainty keeps them in line." };
const _lifeES: Dict = { "dil.cocuk_kavga.t":"Pelea en la escuela", "dil.cocuk_kavga.x":"Un chico grande empuja y maltrata a tu frágil compañero de pupitre; ahora todos los ojos se vuelven hacia ti.", "dil.cocuk_kavga.c0":"Defiende al débil", "dil.cocuk_kavga.c1":"No te metas", "dil.cocuk_kavga.r0":"Te plantaste ante él; saliste algo magullado, pero ese chico no te olvidará jamás.", "dil.cocuk_kavga.r1":"Bajaste la cabeza y seguiste de largo. Te quedó un sabor amargo por dentro.", "dil.cocuk_kese.t":"Una bolsa en el barro", "dil.cocuk_kese.x":"Encontraste una pequeña bolsa en el barro. A lo lejos, un hombre parece estar mirándote.", "dil.cocuk_kese.c0":"Guárdala", "dil.cocuk_kese.c1":"Busca al dueño", "dil.cocuk_kese.r0":"Escondiste la bolsa. Quizá recuerdes esa mirada durante años.", "dil.cocuk_kese.r1":"Le devolviste la bolsa a su dueño; te llamaron \"el niño honrado\".", "dil.cocuk_cirak.t":"La oferta del maestro", "dil.cocuk_cirak.x":"El maestro artesano del barrio te ofrece ser su aprendiz, pero perderás tu tiempo de juego.", "dil.cocuk_cirak.c0":"Acepta el aprendizaje", "dil.cocuk_cirak.c1":"Vive tu niñez", "dil.cocuk_cirak.r0":"De pequeño te entregaste al oficio; mientras los demás jugaban, tú aprendías.", "dil.cocuk_cirak.r1":"Por ahora elegiste el juego; la niñez se vive una sola vez.", "dil.yetiskin_kumar.t":"La trastienda del han", "dil.yetiskin_kumar.x":"Te invitan a la mesa de dados en la trastienda del han. Hay ganancias, pero también deshonra.", "dil.yetiskin_kumar.c0":"Siéntate a la mesa", "dil.yetiskin_kumar.c1":"Vete de allí", "dil.yetiskin_kumar.r0":"Esta noche los dados te sonrieron; pero el dueño de la mesa se grabó tu rostro.", "dil.yetiskin_kumar.r1":"No te enredaste en el juego; tu bolsa está flaca, pero tu conciencia tranquila.", "dil.yetiskin_yangin.t":"El incendio del vecino", "dil.yetiskin_yangin.x":"El establo de tu vecino se ha prendido; las llamas crecen y todos se quedan paralizados.", "dil.yetiskin_yangin.c0":"Acarrea cubos", "dil.yetiskin_yangin.c1":"Mira desde lejos", "dil.yetiskin_yangin.r0":"Te lanzaste al fuego y acarreaste cubos; el pueblo todavía cuenta lo de aquella noche.", "dil.yetiskin_yangin.r1":"No moviste ni un dedo. Te recordarán como el que se quedó quieto esa noche.", "dil.yasli_hac.t":"La caravana de peregrinos", "dil.yasli_hac.x":"Una caravana se pone en camino hacia la peregrinación. ¿Quieres unirte? El camino es largo y penoso.", "dil.yasli_hac.c0":"Ponte en camino", "dil.yasli_hac.c1":"Quédate por ahora", "dil.yasli_hac.r0":"Afrontaste el penoso camino; al volver, te llamaron \"peregrino\".", "dil.yasli_hac.r1":"El viaje quedó para otra primavera; tu intención sigue viva en tu corazón.", "dil.yasli_torun.t":"La curiosidad del nieto", "dil.yasli_torun.x":"Sentado en tu regazo, tu nieto te pregunta por tu pasado: \"¿Cómo eras de joven?\"", "dil.yasli_torun.c0":"Cuenta tu historia", "dil.yasli_torun.c1":"Esquiva la pregunta", "dil.yasli_torun.r0":"Le contaste tu pasado; sus ojos brillaron, y tu nombre vivirá una generación más.", "dil.yasli_torun.r1":"Dijiste \"he vivido muchas cosas\" y lo dejaste pasar; algunos secretos van con uno a la tumba.", "dil.yasli_miras.t":"La sombra de la herencia", "dil.yasli_miras.x":"Tus hijos empezaron a hablar de la herencia mientras aún sigues vivo. Llegó a tus oídos.", "dil.yasli_miras.c0":"Reparte con justicia", "dil.yasli_miras.c1":"Guarda tu secreto", "dil.yasli_miras.r0":"Le dijiste a cada uno su parte sin rodeos; en el hogar quedó la paz.", "dil.yasli_miras.r1":"Mantuviste la boca cerrada; la incertidumbre los mantiene en su sitio." };
const _lifePT: Dict = { "dil.cocuk_kavga.t":"Rixa na Escola", "dil.cocuk_kavga.x":"Um rapaz corpulento empurra e maltrata o teu colega de carteira, mais franzino; os olhos viram-se para ti.", "dil.cocuk_kavga.c0":"Defende o mais fraco", "dil.cocuk_kavga.c1":"Não te metas", "dil.cocuk_kavga.r0":"Plantaste-te à frente dele; levaste alguns sopapos, mas aquele rapaz nunca te há de esquecer.", "dil.cocuk_kavga.r1":"Baixaste a cabeça e passaste em frente. Ficou-te um travo amargo por dentro.", "dil.cocuk_kese.t":"Uma Bolsa na Lama", "dil.cocuk_kese.x":"Encontraste uma pequena bolsa na lama. Ao longe, parece que um homem te observa.", "dil.cocuk_kese.c0":"Mete-a ao bolso", "dil.cocuk_kese.c1":"Procura o dono", "dil.cocuk_kese.r0":"Guardaste a bolsa. Talvez te recordes daquele olhar durante muitos anos.", "dil.cocuk_kese.r1":"Devolveste a bolsa ao dono; ficaste conhecido como o 'rapaz honesto'.", "dil.cocuk_cirak.t":"A Proposta do Mestre", "dil.cocuk_cirak.x":"O mestre do bairro oferece-te um lugar de aprendiz — mas perderás o teu tempo de brincadeira.", "dil.cocuk_cirak.c0":"Aceita a aprendizagem", "dil.cocuk_cirak.c1":"Vive a tua infância", "dil.cocuk_cirak.r0":"Em tenra idade lançaste-te ao trabalho das mãos; enquanto os da tua idade brincavam, tu aprendias.", "dil.cocuk_cirak.r1":"Por agora escolheste a brincadeira; a infância vive-se uma só vez.", "dil.yetiskin_kumar.t":"A Sala dos Fundos da Estalagem", "dil.yetiskin_kumar.x":"Foste convidado para a mesa de dados na sala dos fundos da estalagem. Há ganho, mas também desonra.", "dil.yetiskin_kumar.c0":"Senta-te à mesa", "dil.yetiskin_kumar.c1":"Levanta-te e vai", "dil.yetiskin_kumar.r0":"Esta noite os dados rolaram a teu favor; mas o dono da mesa decorou-te a cara.", "dil.yetiskin_kumar.r1":"Não te meteste no jogo; a bolsa ficou magra, mas a consciência tranquila.", "dil.yetiskin_yangin.t":"O Incêndio do Vizinho", "dil.yetiskin_yangin.x":"O estábulo do vizinho ardeu; as chamas sobem e todos ficaram paralisados.", "dil.yetiskin_yangin.c0":"Carrega baldes", "dil.yetiskin_yangin.c1":"Fica a ver de longe", "dil.yetiskin_yangin.r0":"Mergulhaste no fogo e carregaste baldes; a aldeia ainda conta aquela noite.", "dil.yetiskin_yangin.r1":"Não mexeste um dedo. Serás lembrado como alguém que ficou parado naquela noite.", "dil.yasli_hac.t":"A Caravana da Peregrinação", "dil.yasli_hac.x":"Uma caravana parte em peregrinação. Queres juntar-te? O caminho é longo e penoso.", "dil.yasli_hac.c0":"Mete-te a caminho", "dil.yasli_hac.c1":"Fica por agora", "dil.yasli_hac.r0":"Enfrentaste o caminho penoso; ao regressares, o teu nome foi pronunciado como 'peregrino'.", "dil.yasli_hac.r1":"O caminho ficou para outra primavera; a tua intenção permanece no coração.", "dil.yasli_torun.t":"A Curiosidade do Neto", "dil.yasli_torun.x":"O teu neto, sentado ao teu colo, pergunta pelo teu passado: 'Como eras tu em jovem?'", "dil.yasli_torun.c0":"Conta a tua história", "dil.yasli_torun.c1":"Desconversa", "dil.yasli_torun.r0":"Contaste o teu passado; os olhos dele brilharam, e o teu nome viverá mais uma geração.", "dil.yasli_torun.r1":"Disseste apenas 'vivi muita coisa' e mudaste de assunto; certos segredos vão com um para a sepultura.", "dil.yasli_miras.t":"A Sombra da Herança", "dil.yasli_miras.x":"Os teus filhos começaram a falar da herança ainda tu estás vivo. Chegou-te aos ouvidos.", "dil.yasli_miras.c0":"Reparte com justiça", "dil.yasli_miras.c1":"Guarda o teu segredo", "dil.yasli_miras.r0":"Disseste abertamente a cada um o que lhe cabia; ficou a paz no lar.", "dil.yasli_miras.r1":"Calaste-te bem calado; a incerteza mantém-nos na linha." };
const _lifeAR: Dict = { "dil.cocuk_kavga.t":"شِجارٌ في الكُتّاب", "dil.cocuk_kavga.x":"فتًى ضخمٌ يدفعُ رفيقَك النحيلَ في المقعدِ ويُهينُه، وقد التفتت إليكَ الأنظار.", "dil.cocuk_kavga.c0":"اِنصُر الضعيف", "dil.cocuk_kavga.c1":"لا تتدخّل", "dil.cocuk_kavga.r0":"وقفتَ في وجهِه، فنالكَ بعضُ الأذى، لكنَّ ذلك الفتى لن ينساكَ أبداً.", "dil.cocuk_kavga.r1":"أطرقتَ رأسَكَ ومضيتَ، وبقيت في قلبِكَ غُصّة.", "dil.cocuk_kese.t":"كيسٌ في الوحل", "dil.cocuk_kese.x":"وجدتَ كيساً صغيراً في الوحل، ويبدو أنَّ رجلاً من بعيدٍ يرمُقُك.", "dil.cocuk_kese.c0":"خُذهُ لنفسِك", "dil.cocuk_kese.c1":"اِبحَث عن صاحبِه", "dil.cocuk_kese.r0":"أخفيتَ الكيس، ولعلّكَ تذكُرُ تلك النظراتِ سنينَ طِوالاً.", "dil.cocuk_kese.r1":"أوصلتَ الكيسَ إلى صاحبِه، فذُكِرتَ بـ«الفتى الأمين».", "dil.cocuk_cirak.t":"عَرضُ المُعلّم", "dil.cocuk_cirak.x":"يَعرِضُ عليكَ مُعلّمُ الحارةِ أن تكونَ صَبيّاً عندَه، لكنّكَ ستحرَمُ من وقتِ اللعب.", "dil.cocuk_cirak.c0":"اِغتنم الصَّنعة", "dil.cocuk_cirak.c1":"اِعِش طفولتَك", "dil.cocuk_cirak.r0":"باشرتَ كَدَّ اليدِ في صِغرِك، فبينما يلعبُ أقرانُكَ كنتَ تتعلّم.", "dil.cocuk_cirak.r1":"آثرتَ اللعبَ في الوقتِ الراهن، فالطفولةُ لا تُعاشُ إلّا مرّة.", "dil.yetiskin_kumar.t":"الغُرفةُ الخلفيّةُ للخان", "dil.yetiskin_kumar.x":"دُعِيتَ إلى مائدةِ النَّردِ في الغُرفةِ الخلفيّةِ للخان، فيها مكسبٌ وفيها فضيحة.", "dil.yetiskin_kumar.c0":"اِجلِس للّعب", "dil.yetiskin_kumar.c1":"قُم وانصرِف", "dil.yetiskin_kumar.r0":"مالَ النَّردُ إلى جانبِكَ هذه الليلة، لكنَّ صاحبَ المائدةِ حفِظَ وجهَك.", "dil.yetiskin_kumar.r1":"لم تُلوّث يدَكَ بالقمار، فكيسُكَ خفيفٌ لكنَّ ضميرَكَ مُستريح.", "dil.yetiskin_yangin.t":"حريقُ الجار", "dil.yetiskin_yangin.x":"اِشتعلَ إصطبلُ جارِك، والألسنةُ تتعالى، والناسُ مُتجمّدونَ في أماكنِهم.", "dil.yetiskin_yangin.c0":"اِحمِل الدِّلاء", "dil.yetiskin_yangin.c1":"اُنظُر من بعيد", "dil.yetiskin_yangin.r0":"اِقتحمتَ النارَ وحملتَ الدِّلاء، ولا تزالُ القريةُ تروي تلك الليلة.", "dil.yetiskin_yangin.r1":"لم تتحرّك، فستُذكَرُ تلك الليلةَ بأنّكَ ممّن وقفوا مكتوفي الأيدي.", "dil.yasli_hac.t":"قافلةُ الحجّ", "dil.yasli_hac.x":"قافلةٌ تُيمّمُ دربَ الحجّ، أتُريدُ الانضمامَ إليها؟ الطريقُ طويلٌ شاقّ.", "dil.yasli_hac.c0":"خُذ الطريق", "dil.yasli_hac.c1":"لا تذهب الآن", "dil.yasli_hac.r0":"أقدمتَ على الطريقِ الشاقّ، فلمّا عُدتَ ذُكِرتَ باسمِ «الحاجّ».", "dil.yasli_hac.r1":"تأجّلَ الطريقُ إلى ربيعٍ آخر، لكنَّ نيّتَكَ ثابتةٌ في قلبِك.", "dil.yasli_torun.t":"فُضولُ الحفيد", "dil.yasli_torun.x":"جلسَ حفيدُكَ في حِجرِكَ يسألُ عن ماضيك: «كيف كنتَ في شبابِك؟»", "dil.yasli_torun.c0":"اِروِ حكايتَك", "dil.yasli_torun.c1":"تجاهَل الأمر", "dil.yasli_torun.r0":"رويتَ ماضيكَ فتلألأت عيناه، وسيحيا اسمُكَ جيلاً آخر.", "dil.yasli_torun.r1":"اكتفيتَ بقولِ «عشتُ الكثير» ومضيت، فبعضُ الأسرارِ يذهبُ إلى القبر.", "dil.yasli_miras.t":"ظِلُّ الميراث", "dil.yasli_miras.x":"بدأ أولادُكَ يتحدّثونَ في الميراثِ وأنتَ ما زلتَ على قيدِ الحياة، وقد بلغَكَ ذلك.", "dil.yasli_miras.c0":"اِقسِم بالعدل", "dil.yasli_miras.c1":"اِكتُم سِرَّك", "dil.yasli_miras.r0":"بيّنتَ لكلٍّ حقَّهُ جهاراً، فحلَّ السلامُ في البيت.", "dil.yasli_miras.r1":"أحكمتَ إغلاقَ فمِك، فالغموضُ يُبقيهم على استقامة." };
const _lifeRU: Dict = { "dil.cocuk_kavga.t":"Драка в мектебе", "dil.cocuk_kavga.x":"Рослый мальчишка толкает и пихает твоего щуплого соседа по парте; глаза всех обратились к тебе.", "dil.cocuk_kavga.c0":"Защити слабого", "dil.cocuk_kavga.c1":"Не вмешивайся", "dil.cocuk_kavga.r0":"Ты встал у него на пути; тебя малость поколотили, но тот мальчишка тебя вовек не забудет.", "dil.cocuk_kavga.r1":"Ты опустил голову и прошёл мимо. На сердце осталась горечь.", "dil.cocuk_kese.t":"Кошель в грязи", "dil.cocuk_kese.x":"В грязи ты нашёл маленький кошель. Издалека на тебя будто бы смотрит какой-то человек.", "dil.cocuk_kese.c0":"Сунь в карман", "dil.cocuk_kese.c1":"Найди хозяина", "dil.cocuk_kese.r0":"Ты спрятал кошель. Тот взгляд ты, может, будешь помнить долгие годы.", "dil.cocuk_kese.r1":"Ты вернул кошель хозяину; о тебе пошла молва как о «честном мальчике».", "dil.cocuk_cirak.t":"Предложение мастера", "dil.cocuk_cirak.x":"Мастер из вашего квартала предлагает тебе пойти к нему в подмастерья — но придётся пожертвовать временем для игр.", "dil.cocuk_cirak.c0":"Берись за ремесло", "dil.cocuk_cirak.c1":"Живи детством", "dil.cocuk_cirak.r0":"С малых лет ты взялся за ремесло; пока сверстники играли, ты учился.", "dil.cocuk_cirak.r1":"Покуда ты выбрал игру; детство проживают лишь однажды.", "dil.yetiskin_kumar.t":"Задняя комната хана", "dil.yetiskin_kumar.x":"Тебя позвали к столу с костями в задней комнате хана. Тут и нажива, и позор.", "dil.yetiskin_kumar.c0":"Сядь за стол", "dil.yetiskin_kumar.c1":"Встань и уйди", "dil.yetiskin_kumar.r0":"Этой ночью кости легли в твою пользу; но хозяин стола запомнил твоё лицо.", "dil.yetiskin_kumar.r1":"Ты не связался с игрой; кошель твой тощ, зато совесть чиста.", "dil.yetiskin_yangin.t":"Пожар у соседа", "dil.yetiskin_yangin.x":"Хлев соседа занялся огнём; пламя растёт, а все остолбенели.", "dil.yetiskin_yangin.c0":"Носи вёдра", "dil.yetiskin_yangin.c1":"Гляди издали", "dil.yetiskin_yangin.r0":"Ты бросился в огонь, носил вёдра; деревня по сей день вспоминает ту ночь.", "dil.yetiskin_yangin.r1":"Ты не двинулся с места. Тебя запомнят как того, кто в ту ночь стоял в стороне.", "dil.yasli_hac.t":"Караван паломников", "dil.yasli_hac.x":"Караван собирается в путь к святым местам. Хочешь ли примкнуть? Дорога долга и тяжела.", "dil.yasli_hac.c0":"Отправься в путь", "dil.yasli_hac.c1":"Покуда останься", "dil.yasli_hac.r0":"Ты решился на тяжкий путь; когда вернулся, тебя стали звать «хаджи».", "dil.yasli_hac.r1":"Дорога отложилась до иной весны; намерение твоё хранится в сердце.", "dil.yasli_torun.t":"Любопытство внука", "dil.yasli_torun.x":"Внук уселся к тебе на колено и расспрашивает о прошлом: «А каким ты был в молодости?»", "dil.yasli_torun.c0":"Расскажи свою повесть", "dil.yasli_torun.c1":"Отмахнись", "dil.yasli_torun.r0":"Ты поведал о прошлом; глаза его заблестели, и имя твоё проживёт ещё одно поколение.", "dil.yasli_torun.r1":"Ты сказал «многое повидал» и отмолчался; иные тайны уходят в могилу.", "dil.yasli_miras.t":"Тень наследства", "dil.yasli_miras.x":"Дети твои, пока ты ещё жив, завели речь о наследстве. Слух о том дошёл до тебя.", "dil.yasli_miras.c0":"Раздели по справедливости", "dil.yasli_miras.c1":"Храни молчание", "dil.yasli_miras.r0":"Ты открыто назвал каждому его долю; в доме воцарился покой.", "dil.yasli_miras.r1":"Ты держал язык за зубами; неизвестность держит их в узде." };
