// Hook'suz çevirici — saf modüller (lore vb.) için. Eksik anahtar TR'ye, o da yoksa anahtara düşer.
export function tFor(lang: Lang, key: string): string { return DICTS[lang]?.[key] ?? TR[key] ?? key; }
// %1, %2 … yer tutucularını parametrelerle doldurur (günlük/kronik kayıtları için).
export function applyParams(str: string, p?: (string | number)[]): string {
  return p && p.length ? str.replace(/%(\d+)/g, (_, n) => { const v = p[+n - 1]; return v == null ? "" : String(v); }) : str;
}

// Günlük/olay parametreleri — etiketli isimler render anında dile çözülür:
//  { i: "demir" } → eşya adı · { pl: "Yenişehir" } → yer adı · { c: ["çiftçi", 5] } → meslek unvanı · { pr: "çiftçi" } → meslek adı
const HOUSE_POOLS_I: Record<Lang, string[]> = {
  tr: ["Karaoğulları","Akhanlılar","Demiroğulları","Şahinoğulları","Bozkurtlar","Yıldızoğulları","Çelikhanlar","Aslanoğulları","Toprakoğulları","Gümüşhanlılar","Kayıoğulları","Doğanoğulları"],
  en: ["Blackmane","Ironhold","Falconcrest","Greywolf","Starhaven","Steelborn","Lionheart","Earthford","Silverhall","Hawkwind","Oakenshield","Ravenscar"],
  es: ["Casa Cuervo","Casa Halcón","Casa de Hierro","Casa Lobo","Casa Estrella","Casa Acero","Casa León","Casa Tierra","Casa Plata","Casa Águila","Casa Roble","Casa Toro"],
  pt: ["Casa Corvo","Casa Falcão","Casa do Ferro","Casa Lobo","Casa Estrela","Casa Aço","Casa Leão","Casa Terra","Casa Prata","Casa Águia","Casa Carvalho","Casa Touro"],
  ar: ["بنو غُراب","آل الصقر","بنو الحديد","بنو الذئب","آل النجم","بنو الفولاذ","آل الأسد","بنو الأرض","آل الفضّة","بنو النسر","آل البلّوط","بنو الثور"],
  ru: ["Воронцовы","Соколовы","Железновы","Волковы","Звездины","Стальновы","Львовы","Земцовы","Серебровы","Орловы","Дубовы","Турановы"],
};
export type EvtParam = string | number | { i: string } | { pl: string } | { c: [string, number] } | { pr: string } | { q: string } | { route: string[] } | { fn: [number, "erkek" | "kadın"] } | { pt2: string } | { fc: string } | { wc: number } | { hn: number } | { bl: string } | { enc: string } | { opp: string } | { mev: string } | { wevt: string } | { wevw: string } | { wevl: string } | { cr: string } | { wd: number } | { wds: number[] } | { wai: string } | { invl: string } | { ftl: string } | { goalk: string } | { sfx: string };
function resolveEvtParam(v: EvtParam | undefined, lang: Lang, t: (k: string) => string, female = false): string {
  if (v == null) return "";
  if (typeof v === "object") {
    if ("i" in v) return t("it." + v.i);
    if ("pl" in v) return placeName(v.pl, lang);
    if ("c" in v) return careerTitleL(v.c[0], v.c[1], lang);
    if ("pr" in v) return professionNameL(v.pr, lang);
    if ("q" in v) return t("q." + v.q);
    if ("route" in v) return v.route.map((x) => placeName(x, lang)).join(" → ");
    if ("fn" in v) { const pool = NAME_POOLS[lang] || NAME_POOLS.tr; const arr = v.fn[1] === "erkek" ? pool.m : pool.f; return arr[(v.fn[0] >>> 0) % arr.length]; }
    if ("pt2" in v) return t("pt." + v.pt2); // mülk tipi adı
    if ("fc" in v) return t("fac." + v.fc + ".n"); // fraksiyon adı
    if ("wc" in v) return t("trav.who." + v.wc); // yol arkadaşı türü
    if ("hn" in v) { const hp = HOUSE_POOLS_I[lang] || HOUSE_POOLS_I.tr; return hp[v.hn] ?? HOUSE_POOLS_I.tr[v.hn] ?? ""; }
    if ("bl" in v) return t("beylik." + v.bl);
    if ("enc" in v) return t("enc." + v.enc + ".t");
    if ("opp" in v) return t("opp." + v.opp + ".t");
    if ("mev" in v) return t("mev." + v.mev); // pazar olayı haberi
    if ("wevt" in v) return t("wev." + v.wevt + ".t"); // iş olayı başlığı
    if ("wevw" in v) return t("wev." + v.wevw + ".win"); // iş olayı başarı
    if ("wevl" in v) return t("wev." + v.wevl + ".lose"); // iş olayı başarısızlık
    if ("cr" in v) return t("crime." + v.cr + ".l"); // suç adı
    if ("wd" in v) return t("wound." + v.wd); // yaralanma adı
    if ("wds" in v) return v.wds.map((x) => t("wound." + x)).join(", "); // iyileşen yaralar listesi
    if ("wai" in v) { const wk = "whoami." + v.wai; if (female) { const fv = t(wk + ".f"); if (fv !== wk + ".f") return fv; } return t(wk); } // kim olduğun (aynadaki) — kadın için dişil varyant
    if ("invl" in v) return t("inv." + v.invl + ".l"); // nesil yatırımı adı
    if ("ftl" in v) return t("fac." + v.ftl + ".tl"); // fraksiyon görev etiketi
    if ("goalk" in v) return goalL(v.goalk, lang); // NPC amacı (TR ifadeden çözülür)
    if ("sfx" in v) return v.sfx ? t(v.sfx) : ""; // koşullu ek cümle (anahtarlı)
    return "";
  }
  return String(v);
}
// Bir olay metnini dile göre çöz: anahtar varsa çeviri + etiketli parametreler; yoksa ham metin.
// female=true: kadın oyuncu — çekimli dillerde (ru/ar) o anahtarın ".f" dişil varyantı varsa kullanılır,
// yoksa tabana (eril/nötr) düşer. Günlük hep oyuncuyu (2. şahıs) ya da adını (ölüm) anlattığı için oyuncunun cinsiyeti geçerlidir.
export function renderEvt(k: string | undefined, fallback: string, p: EvtParam[] | undefined, lang: Lang, t: (key: string) => string, female = false): string {
  if (!k) return fallback;
  let tpl: string;
  if (female) {
    const fk = k + ".f";
    const fv = t(fk);
    tpl = fv !== fk ? fv : t(k); // dişil varyant yoksa taban
  } else {
    tpl = t(k);
  }
  if (!p || !p.length) return tpl;
  return tpl.replace(/%(\d+)/g, (_, n) => resolveEvtParam(p[+n - 1], lang, t, female));
}

interface Ctx { lang: Lang; rtl: boolean; setLang: (l: Lang) => void; t: (key: string) => string; }
const LangContext = createContext<Ctx | null>(null);

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>("tr");
  useEffect(() => { (async () => { try { const v = await AsyncStorage.getItem(KEY); if (v && DICTS[v as Lang]) setLangState(v as Lang); } catch {} })(); }, []);
  const setLang = useCallback((l: Lang) => { setLangState(l); AsyncStorage.setItem(KEY, l).catch(() => {}); }, []);
  const t = useCallback((key: string) => DICTS[lang][key] ?? TR[key] ?? key, [lang]);
  const rtl = LANGS.find((l) => l.code === lang)?.rtl ?? false;
  return <LangContext.Provider value={{ lang, rtl, setLang, t }}>{children}</LangContext.Provider>;
}
export function useI18n(): Ctx {
  const c = useContext(LangContext);
  if (!c) throw new Error("useI18n must be used within LanguageProvider");
  return c;
}
